            for j, value in enumerate(poly):
                npoly[j] = (npoly[j] + value) % MOD
                npoly[j + 1] = (npoly[j + 1] + value * other_base) % MOD
            poly = npoly

        for i, value in enumerate(poly):
            r[i] = (r[i] + coef * value) % MOD

    inv = [0] * (N + 1)
    if N >= 1:
        inv[1] = 1
    for i in range(2, N + 1):
        inv[i] = MOD - (MOD // i) * inv[MOD % i] % MOD
